function find_closest_elements(numbers){
    numbers.sort((a, b) => a - b); // Sort the array to make it easier to find the closest elements
    let closestPair = [numbers[0], numbers[1]]; // Initialize the closest pair to the first two elements
    let smallestDifference = numbers[1] - numbers[0]; // Initialize the smallest difference to the first pair

    for (let i = 2; i < numbers.length; i++) {
        let currentDifference = numbers[i] - numbers[i - 1];
        if (currentDifference < smallestDifference) {
            smallestDifference = currentDifference;
            closestPair = [numbers[i - 1], numbers[i]];
        }
    }

    return closestPair;
}

