function max_sum(arr){
  let n = arr.length;
  let dp1 = new Array(n).fill(0); // dp1[i] stores the maximum sum of increasing subsequence up to i
  let dp2 = new Array(n).fill(0); // dp2[i] stores the maximum sum of decreasing subsequence up to i
  let res = 0;

  for (let i = 0; i < n; i++) {
    dp1[i] = arr[i];
    for (let j = 0; j < i; j++) {
      if (arr[i] > arr[j]) {
        dp1[i] = Math.max(dp1[i], dp1[j] + arr[i]);
      }
    }
  }

  for (let i = n - 1; i >= 0; i--) {
    dp2[i] = arr[i];
    for (let j = i + 1; j < n; j++) {
      if (arr[i] > arr[j]) {
        dp2[i] = Math.max(dp2[i], dp2[j] + arr[i]);
      }
    }
  }

  for (let i = 0; i < n; i++) {
    res = Math.max(res, dp1[i] + dp2[i] - arr[i]);
  }

  return res;
}

