function last(arr, x){
  let start = 0;
  let end = arr.length - 1;
  let result = -1;

  while (start <= end) {
    let mid = Math.floor((start + end) / 2);

    if (arr[mid] === x) {
      result = mid;
      start = mid + 1; // Move to the right to find the last occurrence
    } else if (arr[mid] < x) {
      start = mid + 1;
    } else {
      end = mid - 1;
    }
  }

  return result;
}

function last(arr, x) {
  let low = 0;
  let high = arr.length - 1;

  while (low <= high) {
    let mid = Math.floor((low + high) / 2);

    if (arr[mid] === x) {
      low = mid + 1; // Move to the right to find the last occurrence
    } else if (arr[mid] < x) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }

  // If the element is not found, return -1
  return low === arr.length ? -1 : low - 1;
}

function merge_dictionaries_three(dict1, dict2, dict3) {
    // Create a new object to hold the merged results
    const mergedObject = {};

    // Merge dict1 into mergedObject
    for (const key in dict1) {
        mergedObject[key] = dict1[key];
    }

    // Merge dict2 into mergedObject
    for (const key in dict2) {
        if (!mergedObject.hasOwnProperty(key)) { // Check if the key already exists
            mergedObject[key] = dict2[key];
        }
    }

    // Merge dict3 into mergedObject
    for (const key in dict3) {
        if (!mergedObject.hasOwnProperty(key)) { // Check if the key already exists
            mergedObject[key] = dict3[key];
        }
    }

    // Return the merged object
    return mergedObject;
}

