  const size = array.length;
  let i = Math.floor(size / 2 - 1);

  while (i >= 0) {
    heapify(array, size, i);
    i--;
  }

  for (let i = size - 1; i > 0; i--) {
    [array[0], array[i]] = [array[i], array[0]];
