function magic_square_test(my_matrix) {
  // Get the size of the matrix
  let size = my_matrix.length;

  // Check if the matrix is square
  if (my_matrix.length !== my_matrix[0].length) {
    return false;
  }

  // Calculate the sum of the first row
  let sum = my_matrix[0].reduce((acc, val) => acc + val, 0);

  // Check if all rows sum to the same value
  for (let i = 1; i < size; i++) {
    if (my_matrix[i].reduce((acc, val) => acc + val, 0) !== sum) {
      return false;
    }
  }

  // Check if all columns sum to the same value
  for (let i = 0; i < size; i++) {
    let colSum = 0;
    for (let j = 0; j < size; j++) {
      colSum += my_matrix[j][i];
    }
    if (colSum !== sum) {
      return false;
    }
  }

  // Check if the diagonal sums to the same value
  let diagSum1 = 0;
  let diagSum2 = 0;
  for (let i = 0; i < size; i++) {
    diagSum1 += my_matrix[i][i];
    diagSum2 += my_matrix[i][size - 1 - i];
  }
  if (diagSum1 !== sum || diagSum2 !== sum) {
    return false;
  }

  // If all checks pass, the matrix is a magic square
  return true;
}

