    sumColumns[i] = my_matrix.reduce((a, row) => a + row[i], 0);
  }

  // Calculate sum of the first diagonal (top left to bottom right)
  for (let i = 0; i < my_matrix.length; i++) {
    sumDiagonal1 += my_matrix[i][i];
  }

  // Calculate sum of the second diagonal (top right to bottom left)
  for (let i = 0; i < my_matrix.length; i++) {
    sumDiagonal2 += my_matrix[i][my_matrix.length - 1 - i];
  }

  // Check if all sums are equal
