function prime_fib(n) {
  let count = 0;
  let num1 = 0, num2 = 1, fib = num1 + num2;

  while (count < n) {
    if (isPrime(fib)) {
      count++;
      if (count === n) return fib;
    }
    num1 = num2;
    num2 = fib;
    fib = num1 + num2;
  }

  function isPrime(num) {
    if (num <= 1) return false;
    for (let i = 2; i * i <= num; i++) {
      if (num % i === 0) return false;
    }
    return true;
  }
}

