function fib4(n) {
  if (n === 0 || n === 1) return 0;
  if (n === 2) return 2;
  if (n === 3) return 0;

  let fibSequence = [0, 0, 2, 0];
  for (let i = 4; i <= n; i++) {
    fibSequence.push(fibSequence[i - 1] + fibSequence[i - 2] + fibSequence[i - 3] + fibSequence[i - 4]);
  }
  return fibSequence[n];
}

function fib4(n){
    if (n < 0) return null; // Return null for invalid inputs
    if (n === 0 || n === 1) return 0; // Base cases
    if (n === 2) return 2; // Base case
    if (n === 3) return 0; // Base case

    let a = 0, b = 0, c = 2, d = 0, e = 0;
    for (let i = 4; i <= n; i++) {
        e = a + b + c + d;
        a = b;
        b = c;
        c = d;
        d = e;
    }
    return d;
}

