    let left = 0;
    let right = A.length - 1;

    while (left <= right) {
        let mid = Math.floor((left + right) / 2);

        if (A[mid] === x) {
            // If the element is found at the middle position, return it
            return mid;
        } else if (A[mid] < x) {
            // If the element is greater than the middle position, search in the right half
            left = mid + 1;
        } else {
            // If the element is less than the middle position, search in the left half
            right = mid - 1;
        }
    }

    // If no occurrence is found, return -1
    return -1;
}

