    const n = Y.length;
    const o = Z.length;

    // Create a 3D array to store lengths of LCSs of substrings
    const dp = new Array(m + 1).fill(null);
    for (let i = 0; i <= m; i++) {
        dp[i] = new Array(n + 1).fill(null);
        for (let j = 0; j <= n; j++) {
            dp[i][j] = new Array(o + 1).fill(0);
        }
    }

    // Build the DP table
    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            for (let k = 1; k <= o; k++) {
                if (X[i - 1] === Y[j - 1] && Y[j - 1] === Z[k - 1]) {
                    dp[i][j][k] = 1 + dp[i - 1][j - 1][k - 1];
                } else {
                    dp[i][j][k] = Math.max(dp[i - 1][j][k], dp[i][j - 1][k], dp[i][j][k - 1]);
                }
            }
        }
    }

    // The length of the longest common subsequence is in dp[m][n][o]
    return dp[m][n][o];
}

