function magic_square_test(my_matrix) {
  const size = my_matrix.length;

  // Check if the matrix is square
  if (my_matrix.some(row => row.length !== size)) {
    return false;
  }

  // Calculate the sum of the first row to use as a reference
  let sum = 0;
  for (let i = 0; i < size; i++) {
    sum += my_matrix[0][i];
  }

  // Check if all rows have the same sum
  for (let i = 1; i < size; i++) {
    let rowSum = 0;
    for (let j = 0; j < size; j++) {
      rowSum += my_matrix[i][j];
    }
    if (rowSum !== sum) {
      return false;
    }
  }

  // Check if all columns have the same sum
  for (let i = 0; i < size; i++) {
    let colSum = 0;
    for (let j = 0; j < size; j++) {
      colSum += my_matrix[j][i];
    }
    if (colSum !== sum) {
      return false;
    }
  }

  // Check if the diagonals have the same sum
  let diagSum1 = 0, diagSum2 = 0;
  for (let i = 0; i < size; i++) {
    diagSum1 += my_matrix[i][i];
    diagSum2 += my_matrix[size - 1 - i][i];
  }

  if (diagSum1 !== sum || diagSum2 !== sum) {
    return false;
  }

  return true;
}

function magic_square_test(my_matrix) {
  const size = my_matrix.length;
  let sumRow = new Array(size).fill(0);
  let sumCol = new Array(size).fill(0);
  let sumDiag1 = 0;
  let sumDiag2 = 0;

  for (let i = 0; i < size; i++) {
    for (let j = 0; j < size; j++) {
      const value = my_matrix[i][j];

      // Calculate row sum
      sumRow[i] += value;

      // Calculate column sum
      sumCol[j] += value;

      // Calculate diagonal sum (top-left to bottom-right)
      if (i === j) {
        sumDiag1 += value;
      }

      // Calculate diagonal sum (top-right to bottom-left)
      if (i + j === size - 1) {
        sumDiag2 += value;
      }
    }
  }

  // Check if all row sums are equal
  for (let i = 0; i < size; i++) {
    if (sumRow[i] !== sumRow[0]) {
      return false;
    }
  }

  // Check if all column sums are equal
  for (let j = 0; j < size; j++) {
    if (sumCol[j] !== sumCol[0]) {
