function move_one_ball(arr){
    if (arr.length === 0) return true;

    let sortedArr = [...arr].sort((a, b) => a - b);
    for (let i = 0; i < arr.length; i++) {
        if (arr[i] !== sortedArr[i]) {
            // Perform right shift operation
            arr.unshift(arr.pop());
        } else {
            break;
        }
    }

    return arr.join(',') === sortedArr.join(',');
}

