function correct_bracketing(brackets) {
  let balance = 0;

  for (let char of brackets) {
    if (char === '(') {
      balance++;
    } else if (char === ')') {
      balance--;
    }

    // If balance is negative at any point, there's a closing bracket without an opening one
    if (balance < 0) {
      return false;
    }
  }

  // If balance is zero at the end, all brackets are correctly matched
  return balance === 0;
}

