function closest_integer(value) {
    const num = parseFloat(value);
    const floor = Math.floor(num);
    const ceil = Math.ceil(num);
    const diffFloor = num - floor;
    const diffCeil = ceil - num;

    if (diffFloor === diffCeil) {
        return num > 0 ? ceil : floor;
    }
    return diffFloor < diffCeil ? floor : ceil;
}

function closest_integer(value) {
  const num = parseFloat(value);
  const floor = Math.floor(num);
  const ceil = Math.ceil(num);

  if (num - floor === ceil - num) {
    return num > 0 ? ceil : floor;
  } else {
    return Math.abs(floor - num) < Math.abs(ceil - num) ? floor : ceil;
  }
}

function pancake_sort(nums) {
  const n = nums.length;

  for (let i = n; i > 0; i--) {
    let maxIndex = findMaxIndex(nums, i);

    // Move the maximum element to the end
    flipArray(nums, 0, maxIndex);

    // Flip the array to put the maximum element at the beginning
    flipArray(nums, 0, i - 1);
  }

  return nums;
}

function findMaxIndex(nums, n) {
  let maxIndex = 0;
  for (let i = 1; i < n; i++) {
    if (nums[i] > nums[maxIndex]) {
      maxIndex = i;
    }
  }
  return maxIndex;
}

function flipArray(nums, start, end) {
  while (start < end) {
    let temp = nums[start];
    nums[start] = nums[end];
    nums[end] = temp;
    start++;
    end--;
  }
}

