function find_length(string) {
    let maxDiff = -Infinity;
    let zeroCount = 0;
    let oneCount = 0;

    for (let i = 0; i < string.length; i++) {
        if (string[i] === '0') {
            zeroCount++;
        } else {
            oneCount++;
        }

        // Calculate the current difference between zeros and ones
        let currentDiff = zeroCount - oneCount;

        // Update the maximum difference found so far
        maxDiff = Math.max(maxDiff, currentDiff);

        // If the current difference becomes negative, reset both counts as it's not beneficial to have more 1s than 0s at this point
        if (currentDiff < 0) {
            zeroCount = oneCount = 0;
        }
    }

    return maxDiff;
}

