function lps(str) {
  const n = str.length;

  // Create a 2D array to store lengths of longest palindromic subsequence substrings
  const dp = Array.from({ length: n }, () => Array.from({ length: n }, () => 0));

  // Strings of length 1 are palindrome of length 1
  for (let i = 0; i < n; i++) {
    dp[i][i] = 1;
  }

  // Build the table in bottom-up manner
  for (let len = 2; len <= n; len++) {
    for (let start = 0; start < n - len + 1; start++) {
      const end = start + len - 1;

      if (str[start] === str[end]) {
        dp[start][end] = 2 + dp[start + 1][end - 1];
      } else {
        dp[start][end] = Math.max(dp[start + 1][end], dp[start][end - 1]);
      }
    }
  }

  // The length of the longest palindromic subsequence is in dp[0][n-1]
  return dp[0][n - 1];
}

function lps(str) {
  const n = str.length;
  const dp = Array.from({ length: n }, () => Array(n).fill(0));

  for (let i = n - 1; i >= 0; i--) {
    for (let j = i; j < n; j++) {
      if (i === j) {
        dp[i][j] = 1;
      } else if (str[i] === str[j]) {
        dp[i][j] = dp[i + 1][j - 1] + 2;
      } else {
        dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);
      }
    }
  }

  return dp[0][n - 1];
}

