  }

  const size = my_matrix.length;

  // Calculate the sum of the first row to use as a reference
  let total_sum = 0;
  for (let i = 0; i < size; i++) {
    total_sum += my_matrix[0][i];
  }

  // Check if all rows have the same sum
  for (let i = 1; i < size; i++) {
    let row_sum = 0;
    for (let j = 0; j < size; j++) {
      row_sum += my_matrix[i][j];
    }
    if (row_sum !== total_sum) {
      return false;
    }
  }

  // Check if all columns have the same sum
  for (let i = 0; i < size; i++) {
    let col_sum = 0;
    for (let j = 0; j < size; j++) {
      col_sum += my_matrix[j][i];
    }
    if (col_sum !== total_sum) {
      return false;
    }
  }

  // Check if the diagonals have the same sum
  let diag_sum1 = 0;
  let diag_sum2 = 0;

  for (let i = 0; i < size; i++) {
    diag_sum1 += my_matrix[i][i];
    diag_sum2 += my_matrix[i][size - 1 - i];
  }

  if (diag_sum1 !== total_sum || diag_sum2 !== total_sum) {
    return false;
  }

  return true;
}

