  const n = arr.length;

  // Create two arrays to store the maximum sum of increasing and decreasing subsequences ending at each index
  let inc = new Array(n).fill(0);
  let dec = new Array(n).fill(0);

  // Initialize the first element of both arrays
  inc[0] = arr[0];
  dec[n-1] = arr[n-1];

  // Fill the inc array
  for (let i=1; i<n; i++) {
    for (let j=0; j<i; j++) {
      if (arr[i] > arr[j]) {
        inc[i] = Math.max(inc[i], inc[j] + arr[i]);
      }
    }
  }

  // Fill the dec array
  for (let i=n-2; i>=0; i--) {
    for (let j=i+1; j<n; j++) {
      if (arr[i] > arr[j]) {
        dec[i] = Math.max(dec[i], dec[j] + arr[i]);
      }
    }
  }

  // Find the maximum sum of bitonic subsequences
  let max_sum_bitonic = -Infinity;
  for (let i=0; i<n; i++) {
