// Helper function to ensure the subtree rooted at index 'i' is a max-heap
function heapify(arr, i, n) {
    let largest = i;
    let left = 2 * i + 1;
    let right = 2 * i + 2;

    // If left child exists and is greater than the current node
    if (left < n && arr[left] > arr[largest]) {
        largest = left;
    }

    // If right child exists and is greater than the current node
    if (right < n && arr[right] > arr[largest]) {
        largest = right;
    }

    // If the root is not the largest, swap it with the largest element and recursively heapify the affected subtree
    if (largest !== i) {
        [arr[i], arr[largest]] = [arr[largest], arr[i]];
        heapify(arr, largest, n);
    }
}

