function magic_square_test(my_matrix) {
  // Check if the input is a valid matrix (2D array)
  if (!Array.isArray(my_matrix) || my_matrix.length === 0 || !my_matrix.every(row => Array.isArray(row))) {
    return false;
  }

  const size = my_matrix.length;

  // Calculate the sum of each row, column, and diagonal
  let rowSums = [];
  let colSums = [];
  let mainDiagonalSum = 0;
  let secondaryDiagonalSum = 0;

  for (let i = 0; i < size; i++) {
    let rowSum = 0;
    let colSum = 0;

    for (let j = 0; j < size; j++) {
      rowSum += my_matrix[i][j];
      colSum += my_matrix[j][i];

      // Check the main diagonal
      if (i === j) {
        mainDiagonalSum += my_matrix[i][j];
      }

      // Check the secondary diagonal
      if (i + j === size - 1) {
        secondaryDiagonalSum += my_matrix[i][j];
      }
    }

    rowSums.push(rowSum);
    colSums.push(colSum);
  }

  // Check if all sums are equal to each other
  for (let i = 1; i < rowSums.length; i++) {
    if (rowSums[i] !== rowSums[0]) return false;
    if (colSums[i] !== colSums[0]) return false;
  }

  // Check if the main diagonal and secondary diagonal sums are equal
  if (mainDiagonalSum !== secondaryDiagonalSum) return false;

  return true;
}

function magic_square_test(my_matrix) {
    const size = my_matrix.length;
    let sumDiagonal1 = 0;
    let sumDiagonal2 = 0;

    // Calculate the sum of the main diagonal (top-left to bottom-right)
    for(let i=0; i<size; i++) {
        sumDiagonal1 += my_matrix[i][i];
    }

    // Calculate the sum of the secondary diagonal (top-right to bottom-left)
    for(let i=0, j=size-1; i<size; i++, j--) {
        sumDiagonal2 += my_matrix[i][j];
    }

    // Check if all rows have the same sum
    for(let i=0; i<size; i++) {
        let rowSum = 0;
        for(let j=0; j<size; j++) {
            rowSum += my_matrix[i][j];
        }
        if(rowSum !== sumDiagonal1) return false;
    }

    // Check if all columns have the same sum
    for(let i=0; i<size; i++) {
        let colSum = 0;
        for(let j=0; j<size; j++) {
            colSum += my_matrix[j][i];
        }
        if(colSum !== sumDiagonal1) return false;
    }

    // If both diagonals have the same sum, it's a magic square
    return sumDiagonal1 === sumDiagonal2;
}

