function get_median(arr1, arr2, n) {
    let i = 0, j = 0;
    let result = [];

    while (i < n && j < n) {
        if (arr1[i] <= arr2[j]) {
            result.push(arr1[i]);
            i++;
        } else {
            result.push(arr2[j]);
            j++;
        }
    }

    // If there are remaining elements in either array, add them to the result
    while (i < n) {
        result.push(arr1[i]);
        i++;
    }

    while (j < n) {
        result.push(arr2[j]);
        j++;
    }

    // Calculate the median based on the length of the combined array
    let mid = Math.floor(result.length / 2);
    return result.length % 2 === 0 ? (result[mid - 1] + result[mid]) / 2 : result[mid];
}

