      i++;
    } else {
      medians.push(arr2[j]);
      j++;
    }
  }

  // If there are remaining elements in either array, add them to the median list
  while (i < n) {
    medians.push(arr1[i]);
    i++;
  }

  while (j < n) {
    medians.push(arr2[j]);
    j++;
  }

  // Calculate the median based on whether the total number of elements is odd or even
  const mid = Math.floor(medians.length / 2);
  if (medians.length % 2 === 0) {
